function buoyantForce(rhoFluid, V, g){ g=(g==null)?9.81:g; return rhoFluid*g*V; }
function floats(rhoObj, rhoFluid){ return rhoObj <= rhoFluid; }
function displacedVolume(massKg, rhoFluid){ if(!rhoFluid) return NaN; return massKg/rhoFluid; }
function apparentWeight(massKg, rhoObj, rhoFluid, g){ g=(g==null)?9.81:g; var V=massKg/rhoObj; var Fb=buoyantForce(rhoFluid,V,g); return Math.max(0, massKg*g - Fb); }
var EXPORTS={ buoyantForce:buoyantForce, floats:floats, displacedVolume:displacedVolume, apparentWeight:apparentWeight };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BuoyancyForgePure = EXPORTS; }
